import * as THREE from 'three';
export class Controls{
 constructor(player){this.player=player;this.move=new THREE.Vector2();this.keys=new Set();this.joy=document.querySelector('#joy');this.knob=document.querySelector('#knob');this.pointer=null;this.joy.addEventListener('pointerdown',e=>{e.preventDefault();this.pointer=e.pointerId;this.joy.setPointerCapture(e.pointerId);this.rect=this.joy.getBoundingClientRect();this.moveJoy(e)});this.joy.addEventListener('pointermove',e=>{if(e.pointerId===this.pointer)this.moveJoy(e)});const release=e=>{if(e.pointerId===this.pointer){this.pointer=null;this.move.set(0,0);this.knob.style.transform='translate(0,0)'}};this.joy.addEventListener('pointerup',release);this.joy.addEventListener('pointercancel',release);addEventListener('keydown',e=>this.keys.add(e.code));addEventListener('keyup',e=>this.keys.delete(e.code));let lookId=null,lastX=0;document.addEventListener('pointerdown',e=>{if(e.clientX>innerWidth*.38&&!e.target.closest('button')&&!e.target.closest('#joy')&&!e.target.closest('.screen')){lookId=e.pointerId;lastX=e.clientX}});document.addEventListener('pointermove',e=>{if(e.pointerId===lookId&&e.buttons){this.player.yaw-=(e.clientX-lastX)*.006*(this.player.lookScale||1)*(this.player.sens||1);lastX=e.clientX}});document.addEventListener('pointerup',e=>{if(e.pointerId===lookId)lookId=null});}
 moveJoy(e){let x=e.clientX-(this.rect.left+this.rect.width/2),y=e.clientY-(this.rect.top+this.rect.height/2),len=Math.hypot(x,y),r=47;if(len>r){x=x/len*r;y=y/len*r}this.move.set(x/r,-y/r);this.knob.style.transform=`translate(${x}px,${y}px)`}
 update(){if(this.pointer)return;let x=0,y=0;if(this.keys.has('KeyA')||this.keys.has('ArrowLeft'))x--;if(this.keys.has('KeyD')||this.keys.has('ArrowRight'))x++;if(this.keys.has('KeyW')||this.keys.has('ArrowUp'))y++;if(this.keys.has('KeyS')||this.keys.has('ArrowDown'))y--;if(x||y)this.move.set(x,y).normalize();else this.move.set(0,0)}
}
